 'pv-multijunction':['spectrolab-cells'],
 'coverglass':['esa-solar-coverglass','spectrolab-cells','sharp-silicon-cells'],
 'titanium-tank':['northrop-pmd-tanks','northrop-pressurant-tanks','jpl-juno-vault'],
 'copv-carbon':['northrop-pressurant-tanks','nasa-copv'],
 'stainless-tube':['nasa-ammonia-materials'],
 'refractory-nozzle':['ariane-s400'],
